-- ============================================================
-- SQL IMPORT DATA ASET INVENTARIS IT (PT BPR MITRATAMA ARTHABUANA)
-- Dihasilkan otomatis untuk tabel `assets` dan `asset_qr_tokens`
-- ============================================================

USE db_maintenance_qr;

-- 1. Insert Master Assets
ON DUPLICATE KEY UPDATE
    kode_inventaris = VALUES(kode_inventaris),
    merk = VALUES(merk),
    model = VALUES(model),
    serial_number = VALUES(serial_number),
    id_kategori = VALUES(id_kategori),
    id_cabang = VALUES(id_cabang),
    id_divisi = VALUES(id_divisi),
    id_karyawan = VALUES(id_karyawan),
    status = VALUES(status),
    keterangan = VALUES(keterangan),
    ip_address = VALUES(ip_address),
    printer = VALUES(printer),
    updated_at = NOW();

-- 2. Generate QR Tokens untuk seluruh aset yang diimpor
SELECT 
    id AS asset_id,
    SUBSTRING(SHA2(CONCAT('STATIC_QR_MAINTENANCE_KEY_SALT_', id), 256), 1, 32) AS token,
    'Bodi Casing' AS placement_label,
    1 AS is_active
FROM assets
ON DUPLICATE KEY UPDATE
    token = VALUES(token),
    is_active = 1;
